readonly #onMessage = (message: unknown): void => {
		const frame = (message as { chord2?: unknown } | null)?.chord2;
		if (frame === undefined) return;
		try {
			this.deliver(unpackObject(frame) as Frame);
		} catch {
			this.close("protocol error");
		}
	};

